import math

print(math.sqrt(16))
print(math.cos(0))
print(math.pi > 3)
print(math.hypot(3, 4), math.hypot())
print(math.erfc(0), math.tan(0), math.cosh(0), math.asin(0), math.atan(0))
print(math.fsum([0.1, 0.2]) > 0.29, math.sumprod([1, 2], [3, 4]))
